#!/usr/bin/env node
// Receipt runner: invokes the pinned observation_digest_v1.mjs exactly once with the fixed args
// and persists invocation_receipt.json AFTER the run. It never modifies the procedure.
import { spawnSync } from 'node:child_process';
import { readFileSync, writeFileSync, statSync } from 'node:fs';
import { createHash } from 'node:crypto';
import path from 'node:path';

const ws = '/home/nox/.local/share/opencode/worktree/f08b0d/r2-final-autonomy/reports/r2-final-acquisition-1794814017945/state/artifacts/r2-acquisition-731c40a0-d758-49c9-b0cd-27edbda49a14';
const exe = path.join(ws, 'observation_digest_v1.mjs');
const expected = 'e51560a01847a3410c3eedbfe9d261c483e717fe32606220238a0eda757d58db';
const sha = (f) => createHash('sha256').update(readFileSync(f)).digest('hex');

const shaBefore = sha(exe);
if (shaBefore !== expected) {
  process.stderr.write('executable sha256 mismatch: ' + shaBefore + '\n');
  process.exit(3);
}

const fixedArgs = [path.join(ws, 'input', 'pilot.observations.json'), ws];
const argv = [process.execPath, exe, ...fixedArgs];
const startedAt = new Date().toISOString();
const r = spawnSync(argv[0], argv.slice(1), { encoding: 'utf8', cwd: ws });
const completedAt = new Date().toISOString();
const shaAfter = sha(exe);

const outputs = ['digest.json', 'digest.md'].map((n) => {
  const p = path.join(ws, n);
  const st = statSync(p);
  return { path: p, bytes: st.size, sha256: sha(p), mtime: st.mtime.toISOString() };
});
const mtimeSpreadMs = Math.abs(new Date(outputs[0].mtime).getTime() - new Date(outputs[1].mtime).getTime());

const receipt = {
  receipt_version: 1,
  mission_id: 'r2-acquisition-731c40a0-d758-49c9-b0cd-27edbda49a14',
  capability: 'observation-digest-v1',
  written_after_run: true,
  runtime: { node_path: process.execPath, node_version: process.version },
  executable: { path: exe, sha256_before_run: shaBefore, sha256_after_run: shaAfter, declared_sha256: expected, unchanged: shaBefore === shaAfter && shaBefore === expected },
  argv: argv,
  fixed_args: fixedArgs,
  argv_sha256: createHash('sha256').update(JSON.stringify(argv)).digest('hex'),
  cwd: ws,
  started_at: startedAt,
  completed_at: completedAt,
  exit_code: r.status,
  signal: r.signal,
  stdout: r.stdout,
  stderr: r.stderr,
  outputs: outputs,
  output_mtime_spread_ms: mtimeSpreadMs,
  input: { path: fixedArgs[0], sha256: sha(fixedArgs[0]) },
  notes: 'The procedure was authored by the acquisition step; qualification rests on the pinned hash plus independent arithmetic verification, not on third-party vetting. South completion_percent serializes as JSON number 100 because the pinned procedure is immutable.'
};
writeFileSync(path.join(ws, 'invocation_receipt.json'), JSON.stringify(receipt, null, 2) + '\n', 'utf8');
process.stdout.write('receipt written; exit_code=' + r.status + '\n');
process.exit(r.status === 0 ? 0 : 1);
